// Local rehearsal of the production wiring (nothing live is contacted): serves the site files like Netlify would (SPA fallback for /id/*, the /id/api/* proxy rule from
// netlify.toml pointed at a LOCAL backend, support-config.json generated by the real generator from example SUPPORT_* values) on http://localhost:$SITE_PORT.
import http from 'node:http';
import { readFileSync, existsSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';
import { buildSupportConfig } from '../../tools/generate-support-config.mjs';

const ROOT = new URL('../../', import.meta.url).pathname;
const BACKEND = process.env.BACKEND || 'http://127.0.0.1:10123'; const PORT = Number(process.env.SITE_PORT || 8899);
const toml = readFileSync(join(ROOT, 'netlify.toml'), 'utf8');
if (!/from = "\/id\/api\/\*"\s+to = "https:\/\/petali-v2\.onrender\.com\/:splat"/.test(toml)) throw new Error('netlify.toml proxy rule changed: update the rehearsal');
const example = process.env.SUPPORT_ENABLED === '0' ? {} : { SUPPORT_RECIPIENT_NAME: 'Example Recipient', SUPPORT_IBAN: 'CZ65 0800 0000 1920 0014 5399', SUPPORT_BIC: 'GIBACZPX', SUPPORT_CURRENCY: 'EUR', SUPPORT_OWNER_CONFIRMED: 'true' };
const { config } = buildSupportConfig(example);
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json', '.webmanifest': 'application/manifest+json', '.svg': 'image/svg+xml', '.png': 'image/png', '.txt': 'text/plain' };
const log = [];
http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x'); log.push(`${req.method} ${url.pathname}`);
  if (url.pathname === '/__log') { res.end(JSON.stringify(log)); return; }
  if (url.pathname.startsWith('/id/api/')) {
    // (the real browser sends the production origin, so the proxy presents it to the backend)
    const target = BACKEND + '/' + url.pathname.slice('/id/api/'.length) + url.search; const chunks = []; for await (const c of req) chunks.push(c);
    const r = await fetch(target, { method: req.method, headers: { ...Object.fromEntries(Object.entries(req.headers).filter(([k]) => !['host', 'connection', 'content-length', 'origin', 'referer'].includes(k))), ...(req.headers.origin ? { origin: 'https://petali.netlify.app' } : {}) }, body: ['GET', 'HEAD'].includes(req.method) ? undefined : Buffer.concat(chunks), redirect: 'manual' }).catch(() => null);
    if (!r) { res.statusCode = 502; res.end('bad gateway'); return; }
    res.statusCode = r.status; r.headers.forEach((v, k) => { if (!['content-encoding', 'transfer-encoding', 'content-length'].includes(k)) res.setHeader(k, v); }); res.end(Buffer.from(await r.arrayBuffer())); return;
  }
  if (url.pathname === '/support-config.json') { res.setHeader('Content-Type', 'application/json'); res.setHeader('Cache-Control', 'no-store'); res.end(JSON.stringify(config)); return; }
  // Same as netlify.toml: /id/support does not exist (404, never the app shell); /support is answered with support.html.
  if (url.pathname === '/id/support' || url.pathname.startsWith('/id/support/')) { res.statusCode = 404; res.end('not found'); return; }
  const route = url.pathname.replace(/\/+$/, '') === '/support' ? '/support.html' : url.pathname;
  let p = join(ROOT, decodeURIComponent(route)); const real = existsSync(p) && statSync(p).isFile();
  if (!real) { if (url.pathname === '/id' || url.pathname.startsWith('/id/')) p = join(ROOT, 'id/index.html'); else { res.statusCode = 404; res.end('not found'); return; } }
  res.setHeader('Content-Type', types[extname(p)] || 'application/octet-stream'); res.end(readFileSync(p));
}).listen(PORT, '127.0.0.1', () => console.log(`rehearsal site on ${PORT}`));
